export function intelligenceHealth(capabilities=[]){if(!capabilities.length)return{state:'UNKNOWN',active:0,shadow:0,blocked:0};let active=0,shadow=0,blocked=0;for(const c of capabilities){if(c.releaseState==='ACTIVE'&&c.providerHealthy===true)active++;else if(c.releaseState==='SHADOW'&&c.providerHealthy!==false)shadow++;else blocked++;}const state=blocked===0?'HEALTHY':active+shadow>0?'DEGRADED':'UNAVAILABLE';return{state,active,shadow,blocked,total:capabilities.length};}
